from rest_framework.throttling import SimpleRateThrottle
from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions
from .models import TenantAnalytics

class OrganizationRateThrottle(SimpleRateThrottle):
    scope = 'org_analytics'

    def get_cache_key(self, request, view):
        # Lock rate limit bucket to the authenticated user's organization slug
        if not request.user or not request.user.is_authenticated or not hasattr(request.user, 'organization'):
            return None
        return f"throttle_{self.scope}_{request.user.organization.slug}"

class TenantAnalyticsReportView(APIView):
    permission_classes = [permissions.IsAuthenticated]
    throttle_classes = [OrganizationRateThrottle]

    def get(self, request):
        org = request.user.organization
        data = TenantAnalytics.objects.filter(tenant=org).first()
        return Response({"tenant": org.slug, "metrics": data.metrics if data else {}})
